// Network status for every page: a small indicator in the site bar and friendly notices when an outside service
// (SIMBAD, VizieR, MAST, an archive) cannot be reached. The site itself works without a connection once the service
// worker (public/sw.js, generated by tools/build_sw.mjs) has saved it; only live queries need the internet.
//
//   fetchOr(url, { what, fallback, as, timeout, quiet404, ...fetchInit })
//     what      the service, in words ("SIMBAD", "the MAST archive"); named in the notice
//     fallback  returned (or called with the error, if a function) when the request fails; without it the call
//               throws an Error whose message is the same friendly sentence
//     as        'response' (default: the Response), 'text', 'json' or 'arrayBuffer'
//     timeout   milliseconds before giving up (default 30000; 0 for none, e.g. a long download); a caller's own `signal` aborting is not a failure
//               worth a notice and is rethrown as is
//     quiet404  a 404 is an answer (no such file), not an outage: no notice
//   reportDown(what, err) / reportUp(what): for callers with their own fetch loop (mirrors, progress readers)
//   netState(): { online, down: [services] } · 'esl-net' events on window when it changes
//
// Pure DOM, no imports: pages load it through nav.js; it is safe to import in Node (does nothing without a document).

const hasDoc = typeof document !== 'undefined';
const down = new Map();            // service -> { at, message }
const lastNotice = new Map();      // service -> time of its last notice, so a retry loop does not stack them
let sameOriginMiss = false;        // a same-origin fetch failed: the site itself is unreachable (offline)

export const isOnline = () => typeof navigator === 'undefined' || navigator.onLine !== false;

/** The friendly sentence for a failed request. */
export function describeNetFailure(what, err, status, url) {
  const name = what || 'This service';
  if (url && sameOrigin(url) && (!isOnline() || !status)) return `${name} is not saved on this device yet; it will be once you are back online. The rest of the page works.`;
  if (!isOnline()) return `You are offline: ${name} needs the internet. The rest of the page works.`;
  if (err && err.name === 'TimeoutError') return `${name} did not answer in time; the rest of the page works. Try again later.`;
  if (status >= 500) return `${name} is having trouble right now (HTTP ${status}); the rest of the page works. Try again later.`;
  if (status) return `${name} refused the request (HTTP ${status}); the rest of the page works.`;
  return `${name} is not reachable right now; the rest of the page works.`;
}

export function netState() { return { online: isOnline() && !sameOriginMiss, down: [...down.keys()] }; }
const changed = () => { if (typeof window !== 'undefined' && typeof CustomEvent === 'function') window.dispatchEvent(new CustomEvent('esl-net', { detail: netState() })); render(); };

/** A service failed: remember it, show a notice (once a minute per service). */
export function reportDown(what, err, status, url) {
  const message = describeNetFailure(what, err, status, url);
  down.set(what || 'a service', { at: Date.now(), message });
  const t = lastNotice.get(what) || 0;
  if (Date.now() - t > 60000) { lastNotice.set(what, Date.now()); notify(message); }
  changed();
  return message;
}
/** A service answered again. */
export function reportUp(what) { if (down.delete(what)) changed(); }

const sameOrigin = (url) => { try { return typeof location !== 'undefined' && new URL(url, location.href).origin === location.origin; } catch { return false; } };

/** JSON from the site itself (a catalogue shard, an example): a notice if it is not saved offline yet. */
export const siteJson = (url, what = 'This file of the site') => fetchOr(String(url), { what, as: 'json' });

/** fetch, with failures turned into a notice naming the service and a fallback value (see the top of this file). */
export async function fetchOr(url, opts = {}) {
  const { what, fallback, as = 'response', timeout = 30000, quiet404 = false, signal, ...init } = opts;
  const hasFallback = Object.prototype.hasOwnProperty.call(opts, 'fallback');
  const timer = timeout > 0 && typeof AbortSignal !== 'undefined' && AbortSignal.timeout ? AbortSignal.timeout(timeout) : null;   // 0: no limit
  const sig = signal && timer && AbortSignal.any ? AbortSignal.any([signal, timer]) : (signal || timer || undefined);
  let status = 0, err = null;
  try {
    const r = await fetch(url, sig ? { ...init, signal: sig } : init);
    if (r.ok) {
      const out = as === 'text' ? await r.text() : as === 'json' ? await r.json() : as === 'arrayBuffer' ? await r.arrayBuffer() : r;
      reportUp(what); if (sameOrigin(url) && sameOriginMiss) { sameOriginMiss = false; changed(); }
      return out;
    }
    status = r.status; err = new Error(`HTTP ${r.status}`);
  } catch (e) {
    if (signal && signal.aborted) throw e;                      // the caller cancelled: not an outage
    err = e && e.name === 'AbortError' && timer && timer.aborted ? Object.assign(new Error('timeout'), { name: 'TimeoutError' }) : e;
    if (sameOrigin(url)) { sameOriginMiss = true; }
  }
  const message = status === 404 && quiet404 ? `${what || url}: not found (HTTP 404)` : reportDown(what, err, status, url);
  if (hasFallback) return typeof fallback === 'function' ? fallback(err, status) : fallback;
  throw Object.assign(new Error(message), { status, cause: err, friendly: true });
}

// ---------------------------------------------------------------- the indicator and the notices

let pill = null, box = null;
function ensurePill() {
  if (!hasDoc) return null;
  const bar = document.getElementById('sitebar');
  if (!bar) return null;
  if (pill && bar.contains(pill)) return pill;
  pill = document.createElement('span');
  pill.className = 'sitenet'; pill.id = 'sitenet'; pill.setAttribute('role', 'status'); pill.hidden = true;
  const tag = bar.querySelector('.sitetag'), brand = bar.querySelector('.sitebrand');
  const after = tag || brand;
  if (after) after.after(pill); else bar.prepend(pill);
  return pill;
}

function render() {
  const p = ensurePill(); if (!p) return;
  const was = p.hidden;
  draw(p);
  // the bar fits its links to the room left (nav.js compactNav, on resize): the pill takes some of it
  if (was !== p.hidden && typeof window !== 'undefined') window.dispatchEvent(new Event('resize'));
}
function draw(p) {
  const st = netState();
  if (!st.online) {
    p.hidden = false; p.dataset.state = 'offline';
    p.innerHTML = '<i aria-hidden="true"></i><span class="sn-l">Offline: using the saved copy</span><span class="sn-s" aria-hidden="true">Offline</span>';
    p.setAttribute('aria-label', 'Offline: using the saved copy');
    p.title = 'No connection. Pages, examples and catalogue snapshots saved on this device keep working; live archive queries wait for the connection.';
  } else if (st.down.length) {
    p.hidden = false; p.dataset.state = 'degraded';
    const n = st.down.length;
    p.innerHTML = `<i aria-hidden="true"></i><span class="sn-l">${n === 1 ? esc(st.down[0]) + ' unreachable' : n + ' services unreachable'}</span><span class="sn-s" aria-hidden="true">${n}</span>`;
    p.title = st.down.map((w) => down.get(w).message).join('\n');
    p.setAttribute('aria-label', p.title);
  } else { p.hidden = true; p.removeAttribute('data-state'); p.removeAttribute('aria-label'); }
}
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

/** A small notice, bottom left, that fades by itself; `opts.action` { label, run } adds a button. */
export function notify(message, opts = {}) {
  if (!hasDoc || !document.body) { if (typeof console !== 'undefined') console.warn(message); return null; }
  if (!box || !document.body.contains(box)) {
    box = document.createElement('div'); box.className = 'sitenotices'; box.setAttribute('role', 'status'); box.setAttribute('aria-live', 'polite');
    document.body.append(box);
  }
  for (const n of box.children) if (n.dataset.msg === message) return n;   // the same notice is already up
  const n = document.createElement('div'); n.className = 'sitenotice'; n.dataset.msg = message;
  const t = document.createElement('span'); t.textContent = message; n.append(t);
  if (opts.action) { const b = document.createElement('button'); b.type = 'button'; b.className = 'sn-act'; b.textContent = opts.action.label; b.addEventListener('click', () => { opts.action.run(); n.remove(); }); n.append(b); }
  const x = document.createElement('button'); x.type = 'button'; x.className = 'sn-x'; x.setAttribute('aria-label', 'Dismiss'); x.textContent = '×'; x.addEventListener('click', () => n.remove()); n.append(x);
  box.append(n);
  while (box.children.length > 3) box.firstChild.remove();
  const ms = opts.sticky ? 0 : opts.ms || 9000;
  if (ms) setTimeout(() => n.remove(), ms);
  return n;
}

/** Mount the indicator; nav.js calls this after building the bar (again after a rebuild: it re-inserts itself). */
export function mountNet() {
  if (!hasDoc) return;
  if (window.__eslNet) { render(); return; }
  window.__eslNet = true;
  window.addEventListener('online', () => { sameOriginMiss = false; changed(); });
  window.addEventListener('offline', changed);
  render();
}
